CREATE OR REPLACE FUNCTION public.normalize_turkish(input_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
  result TEXT;
BEGIN
  IF input_text IS NULL THEN
    RETURN NULL;
  END IF;

  result := LOWER(input_text);
  result := REPLACE(result, 'ı', 'i');
  result := REPLACE(result, 'İ', 'i');
  result := REPLACE(result, 'ş', 's');
  result := REPLACE(result, 'Ş', 's');
  result := REPLACE(result, 'ğ', 'g');
  result := REPLACE(result, 'Ğ', 'g');
  result := REPLACE(result, 'ç', 'c');
  result := REPLACE(result, 'Ç', 'c');
  result := REPLACE(result, 'ö', 'o');
  result := REPLACE(result, 'Ö', 'o');
  result := REPLACE(result, 'ü', 'u');
  result := REPLACE(result, 'Ü', 'u');

  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_user_streak(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current_streak int := 0;
  v_longest_streak int := 0;
  v_running_streak int := 0;
  v_prev_date date := null;
  v_last_entry_date date := null;
  entry_record record;
begin
  if p_user_id is null then
    raise exception 'User ID cannot be null';
  end if;

  v_current_streak := public.calculate_streak(p_user_id);

  for entry_record in
    select entry_date
    from public.gratitude_entries
    where user_id = p_user_id
      and coalesce(jsonb_array_length(statements), 0) > 0
    order by entry_date asc
  loop
    if v_prev_date is null then
      v_running_streak := 1;
    elsif entry_record.entry_date = v_prev_date + interval '1 day' then
      v_running_streak := v_running_streak + 1;
    elsif entry_record.entry_date = v_prev_date then
      -- Duplicate day (shouldn't happen, but be safe).
      null;
    else
      v_running_streak := 1;
    end if;

    if v_running_streak > v_longest_streak then
      v_longest_streak := v_running_streak;
    end if;

    v_prev_date := entry_record.entry_date;
    v_last_entry_date := entry_record.entry_date;
  end loop;

  v_longest_streak := greatest(v_longest_streak, v_current_streak);

  insert into public.streaks (user_id, current_streak, longest_streak, last_entry_date, created_at, updated_at)
  values (p_user_id, v_current_streak, v_longest_streak, v_last_entry_date, now(), now())
  on conflict (user_id) do update
    set current_streak = excluded.current_streak,
        longest_streak = greatest(public.streaks.longest_streak, excluded.longest_streak),
        last_entry_date = excluded.last_entry_date,
        updated_at = now();
end;
$function$

CREATE OR REPLACE FUNCTION public.register_push_token(p_token text, p_timezone text DEFAULT NULL::text, p_token_type text DEFAULT 'expo'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_now timestamptz := now();
  v_reassigned_tokens text[] := ARRAY[]::text[];
  v_returned_token text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING errcode = '28000';
  END IF;

  IF coalesce(trim(p_token), '') = '' THEN
    RAISE EXCEPTION 'Token is required';
  END IF;

  -- If the token already exists, reassign it to the current user
  FOR v_returned_token IN
    UPDATE public.push_tokens
       SET user_id = v_user_id,
           token_type = coalesce(p_token_type, token_type),
           created_at = v_now
     WHERE token = p_token
     RETURNING token
  LOOP
    v_reassigned_tokens := array_append(v_reassigned_tokens, v_returned_token);
  END LOOP;

  -- If no rows were updated, insert the new token
  IF coalesce(array_length(v_reassigned_tokens, 1), 0) = 0 THEN
    INSERT INTO public.push_tokens (user_id, token, token_type, created_at)
    VALUES (v_user_id, p_token, coalesce(p_token_type, 'expo'), v_now)
    ON CONFLICT (token) DO UPDATE
      SET user_id = excluded.user_id,
          token_type = excluded.token_type,
          created_at = excluded.created_at;
  END IF;

  -- Optionally update the user’s timezone
  IF p_timezone IS NOT NULL THEN
    UPDATE public.profiles
       SET timezone = p_timezone,
           updated_at = v_now
     WHERE id = v_user_id;
  END IF;

  RETURN json_build_object(
    'inserted_token', p_token,
    'reassigned_tokens', v_reassigned_tokens
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_daily_gratitude_statements(p_entry_date date, p_statements jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_is_pro boolean := false;
  v_timezone text;
  v_today date;
  v_count integer := coalesce(jsonb_array_length(coalesce(p_statements, '[]'::jsonb)), 0);
begin
  if v_user_id is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select coalesce(is_pro, false), timezone
    into v_is_pro, v_timezone
  from public.profiles
  where id = v_user_id;

  v_today := case
    when v_timezone is not null then (now() at time zone v_timezone)::date
    else current_date
  end;

  if not v_is_pro and p_entry_date <> v_today then
    raise exception 'PAST_ENTRY_REQUIRES_PRO'
      using errcode = 'P0001';
  end if;

  if not v_is_pro and v_count > 1 then
    raise exception 'FREE_DAILY_LIMIT_REACHED'
      using errcode = 'P0001';
  end if;

  insert into public.gratitude_entries (user_id, entry_date, statements, created_at, updated_at)
  values (v_user_id, p_entry_date, coalesce(p_statements, '[]'::jsonb), now(), now())
  on conflict (user_id, entry_date)
  do update set
    statements = excluded.statements,
    updated_at = now();
end;
$function$

CREATE OR REPLACE FUNCTION public.set_statement_mood(p_entry_date date, p_statement_index integer, p_mood text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_row_id uuid;
  v_moods jsonb;
  v_len int;
  v_clean_mood text := nullif(trim(coalesce(p_mood, '')), '');
  v_is_pro boolean := false;
begin
  if v_user_id is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select coalesce(is_pro, false)
    into v_is_pro
  from public.profiles
  where id = v_user_id;

  if not v_is_pro then
    raise exception 'MOOD_EDITING_REQUIRES_PRO'
      using errcode = 'P0001';
  end if;

  select id, coalesce(moods, '{}'::jsonb), coalesce(jsonb_array_length(statements), 0)
    into v_row_id, v_moods, v_len
  from public.gratitude_entries
  where user_id = v_user_id and entry_date = p_entry_date
  for update;

  if not found then
    raise exception 'Entry not found for date %', p_entry_date using errcode = 'P0002';
  end if;

  if p_statement_index < 0 or p_statement_index >= v_len then
    raise exception 'Invalid statement index % (length %)', p_statement_index, v_len
      using errcode = '22003';
  end if;

  if v_clean_mood is null then
    update public.gratitude_entries
    set moods = v_moods - (p_statement_index)::text,
        updated_at = now()
    where id = v_row_id;
  else
    update public.gratitude_entries
    set moods = jsonb_set(v_moods, array[(p_statement_index)::text], to_jsonb(v_clean_mood), true),
        updated_at = now()
    where id = v_row_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.trigger_wrapper_update_user_streak()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF (TG_OP = 'INSERT' OR TG_OP = 'UPDATE') THEN
        PERFORM public.update_user_streak();
        RETURN NEW;
    ELSIF (TG_OP = 'DELETE') THEN
        PERFORM public.update_user_streak();
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
   NEW.updated_at = now(); 
   RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_user_streak()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
begin
  v_user_id := coalesce(new.user_id, old.user_id);
  if v_user_id is not null then
    perform public.recalculate_user_streak(v_user_id);
  end if;
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_profile_timezone()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.timezone is null then
    return new;
  end if;

  if not exists (
    select 1 from pg_timezone_names where name = new.timezone
  ) then
    raise exception 'Invalid IANA timezone: %', new.timezone
      using errcode = '22023';
  end if;

  return new;
end;
$function$
